/* Examine the Past: page-scoped Bloom's Taxonomy enrichment (no navigation transition edits). */
(()=>{'use strict';if(window.ETPBloomsRefinement)return;window.ETPBloomsRefinement=true;
const $=(sel,root=document)=>root.querySelector(sel),all=(sel,root=document)=>Array.from(root.querySelectorAll(sel));
const levels=['remember','understand','apply','analyze','evaluate','create'];
const levelInfo={
remember:{goal:'Retrieve reliable knowledge and establish chronology before making interpretations.',verbs:'identify • name • locate • sequence • define',example:'For the Industrial Revolution, identify where early textile mechanization developed and name major inventions, workers, and changes in production.',evidence:'Students accurately identify people, terms, places, dates and basic relationships; a timeline or labeled map can reveal misconceptions.',extension:'Ask students to check two reference sources and explain why a date or definition is reliable.'},
understand:{goal:'Explain historical meaning in your own words, including cause and consequence.',verbs:'summarize • explain • classify • compare • describe',example:'Explain how factory work changed the daily lives of children and families during industrialization.',evidence:'Students summarize change and continuity using accurate examples instead of simply repeating a definition.',extension:'Pair a worker’s account with an image and distinguish what each source reveals.'},
apply:{goal:'Use knowledge and disciplinary tools in a relevant unfamiliar situation.',verbs:'use • map • illustrate • demonstrate • organize',example:'Apply a map key and a timeline to explain why industrial towns grew near coalfields, transport routes, or ports.',evidence:'Students transfer what they learned to a source, map, graph, case study or scenario.',extension:'Have students test their explanation against an unfamiliar historical example.'},
analyze:{goal:'Break complex developments into relationships, perspectives and patterns.',verbs:'differentiate • investigate • compare • connect • categorize',example:'Analyze how industrialization affected owners and workers differently and connect changes in technology, migration and urbanization.',evidence:'Students support claims with source evidence and distinguish correlation from a plausible historical cause.',extension:'Compare two sources representing different interests or viewpoints.'},
evaluate:{goal:'Judge interpretations or decisions using explicit criteria and historical evidence.',verbs:'assess • defend • critique • prioritize • justify',example:'Evaluate whether early industrialization brought more benefits than harms to working families, accounting for historical context.',evidence:'Students state criteria, weigh competing evidence, acknowledge limitations and justify a conclusion.',extension:'Revise the judgment after examining a source that challenges the initial claim.'},
create:{goal:'Produce an original evidence-based historical interpretation or learning product.',verbs:'design • construct • compose • propose • synthesize',example:'Design a museum panel that uses primary sources, a timeline and a map to tell a balanced story of industrialization.',evidence:'Students synthesize defensible claims from sourced evidence and explain the choices behind their product.',extension:'Invite peer critique for accuracy, representation and citation quality.'}
};
const bank=[
{key:'industrial',pattern:/industrial revolution|industrialization|factory system|textile mills?|steam engine/i,topic:'the Industrial Revolution',anchor:'industrialization, factory labor, mechanization, urbanization, and change over time',source:'factory testimony, population maps, historical photographs, and production records',q:['Which inventions and production changes helped begin the Industrial Revolution, and where did major early developments occur?','How did mechanization change work and everyday life for women, children, and men?','How could a map of coalfields, rivers, ports, and cities help explain industrial growth?','What connections can you trace among factory production, urbanization, migration, labor reform, and environmental change?','To what extent did industrialization improve life for different social groups, based on contemporary evidence?','How would you design a balanced museum exhibit about the Industrial Revolution using three different types of historical sources?'],answer:['Steam-powered machinery, textile innovations, coal and factory production; early developments were concentrated in Britain, with later expansion elsewhere.','Many people moved from home-based or agricultural production to wage labor and factory schedules; experiences varied by class, age, gender and region.','Energy supplies, markets, raw materials and transportation routes made some places advantageous; maps should be compared with dated economic evidence.','Growth in production and cities was related to changing employment and migration patterns; the relationships were not identical everywhere.','A defensible response weighs higher output and eventual improvements against dangerous working conditions, inequality and pollution, using dated evidence.','A strong exhibit includes an argument, artifacts, multiple perspectives, geographic and chronological context, and source citations.']},
{key:'war',pattern:/\bwar\b|world war|civil war|revolutionary war|conflict|battle/i,topic:'war and its historical consequences',anchor:'causes, chronology, geography, diplomacy, military and civilian perspectives',source:'maps, diplomatic correspondence, contemporary newspapers, oral histories, and government records',q:['Which major actors, dates, locations, and turning points define the conflict you are studying?','How did political goals, alliances, resources, and geography shape the causes of this war?','How could you use a map and timeline to explain changes in strategy and movement?','How were civilians, leaders, and soldiers affected differently, and what patterns explain these differences?','Which explanation of the war’s causes is most convincing when tested against primary-source evidence?','How could you construct an evidence-based exhibit showing multiple perspectives on this conflict?'],answer:['Name the specific conflict first; identify its major participants, chronology and geography from credible sources.','Evaluate long-term conditions separately from immediate triggers, including political and economic motivations.','Use accurate time-stamped maps to connect terrain, supply routes, and decision-making.','Compare experiences by location, social position and access to resources; avoid treating any group as uniform.','Weigh competing causes against documents and context rather than assuming there was one simple reason.','Include civilian and combatant voices, sources from different sides, contextual captions and uncertainty where records conflict.']},
{key:'civilrights',pattern:/civil rights|segregation|jim crow|voting rights|brown v\.? board/i,topic:'the U.S. Civil Rights Movement',anchor:'constitutional rights, community organizing, nonviolent protest, federalism and historical change',source:'court decisions, speeches, oral histories, photographs and voting-rights records',q:['What laws, organizations, leaders, and events shaped the Civil Rights Movement?','Why did activists use different strategies to challenge segregation and discrimination?','How would you use court cases and local records to explain implementation of federal civil-rights rulings?','How did grassroots organizing, media coverage, public opinion and federal action interact?','How effectively did specific legislative and judicial changes address barriers to equality?','How could you create a local civil-rights history project grounded in oral histories and archival sources?'],answer:['Examples include Brown v. Board of Education (1954), the Civil Rights Act (1964), and the Voting Rights Act (1965).','Different methods targeted legal, political, economic and social barriers, often in complementary ways.','Distinguish the text of a ruling from local responses and enforcement over time.','Connect sustained local activism with national developments without erasing differences among communities.','Use explicit criteria and data; distinguish statutory change from actual lived outcomes.','Develop focused questions, informed consent for interviews, a timeline, and responsibly cited historical evidence.']},
{key:'geography',pattern:/migration|geograph|map|trade routes?|silk road|environment/i,topic:'historical geography and human movement',anchor:'spatial patterns, migration, environment, trade routes and diffusion',source:'historical maps, census records, travelers’ accounts and archaeological findings',q:['Which regions, routes, resources and physical features are central to this topic?','How did geography influence the opportunities and constraints of people in this period?','How would you use two maps from different dates to demonstrate change?','How did environment, technology, trade and political boundaries influence migration patterns?','Which evidence best supports a proposed explanation of population movement?','How could you design an annotated map that communicates a historically defensible geographic argument?'],answer:['Locate places and describe the reliability and date of the maps used.','Geography affects choices but does not fully determine historical outcomes.','Compare scale, symbols, borders and source dates before inferring change.','Consider push-and-pull factors alongside political and cultural context.','Use multiple geographic and documentary sources and account for missing data.','Build a legend, dated layers, evidence citations, and a clear historical claim.']}
];
const genericQ={
remember:t=>['What five people, places, dates, events, or terms are essential for understanding '+t+'?','Where and when did the principal developments connected with '+t+' take place?','Which two primary or reliable secondary sources help establish basic facts about '+t+'?','What are the major events in a chronological outline of '+t+'?'],
understand:t=>['How would you explain the most important causes and consequences of '+t+' to a younger student?','How did different groups experience '+t+'?','Which changes and continuities are visible across the period associated with '+t+'?','What does a selected primary source help us understand about '+t+'?'],
apply:t=>['How could a historical map and timeline be used to investigate '+t+'?','How would you classify evidence about '+t+' into political, economic, social and geographic categories?','How could you apply sourcing and contextualization to a document about '+t+'?','What can an unfamiliar image or data set reveal about '+t+' when compared with your existing knowledge?'],
analyze:t=>['What relationships can you identify among the causes, events and consequences of '+t+'?','How do two different perspectives on '+t+' compare?','What patterns and contradictions emerge from evidence about '+t+'?','How did geography, technology and institutions shape the course of '+t+'?'],
evaluate:t=>['Which interpretation of '+t+' is most convincing, and what evidence supports your judgment?','How reliable is a selected source about '+t+' when its author, purpose and context are considered?','To what extent was '+t+' a turning point?','What is missing from a popular narrative of '+t+'?'],
create:t=>['How could you design a museum exhibit or documentary storyboard about '+t+' using cited evidence?','What historical argument about '+t+' could you construct from three sources?','How could you create a thematic map or timeline communicating a nuanced interpretation of '+t+'?','How would you design a comparative inquiry featuring conflicting perspectives on '+t+'?']
};
function findByText(re){return all('h1,h2,h3,h4,button,a,span,strong').find(e=>re.test(e.textContent.trim())&&e.children.length<5)}
function tip(){let nodes=all('[title],[data-tooltip],[aria-label]');let popup;const show=(el,e)=>{const title=el.getAttribute('data-etp-tip-original');if(!title)return;popup??=document.createElement('div');popup.className='etp-bloom-hover-tip';popup.textContent=title;document.body.appendChild(popup);const rect=el.getBoundingClientRect();const top=Math.max(4,rect.top-42);popup.style.left=Math.max(8,Math.min(innerWidth-popup.offsetWidth-8,rect.left+rect.width/2-popup.offsetWidth/2))+'px';popup.style.top=top+'px'};nodes.forEach(el=>{if(el.closest('#etp-blooms-app')===null)return;const v=el.getAttribute('title')||el.getAttribute('data-tooltip');if(!v||el.dataset.etpTipOriginal)return;el.dataset.etpTipOriginal=v;el.removeAttribute('title');el.addEventListener('mouseenter',e=>show(el,e));el.addEventListener('focus',e=>show(el,e));el.addEventListener('mouseleave',()=>popup?.remove());el.addEventListener('blur',()=>popup?.remove())});}
function sticky(){const text=findByText(/interactive pyramid/i);const nav=text?.closest('nav')||text?.parentElement?.closest('nav')||$('.bloom-nav')||$('.section-nav');if(nav){nav.classList.add('etp-bloom-nav-enhanced');nav.style.scrollMarginTop='80px'}const app=$('#etp-blooms-app');if(app){const candidates=all('nav',app);candidates.filter(n=>/interactive pyramid|question builder|six levels/i.test(n.textContent)).forEach(n=>n.classList.add('etp-bloom-nav-enhanced'))}}
function details(){all('[data-info-level]').forEach(btn=>{if(btn.dataset.etpEnhancedLevel)return;btn.dataset.etpEnhancedLevel='yes';btn.addEventListener('click',()=>{let key=btn.dataset.infoLevel?.toLowerCase(),d=levelInfo[key];if(!d)return;setTimeout(()=>{let place=$('.level-detail')||btn.closest('.ladder')?.nextElementSibling;if(!place)return;let ex=$('.etp-bloom-level-extra',place);if(ex)ex.remove();let box=document.createElement('div');box.className='etp-bloom-level-extra';box.innerHTML='<h4>Deeper history-classroom interpretation</h4><p><b>Purpose:</b> '+d.goal+'</p><p><b>Historical thinking verbs:</b> '+d.verbs+'</p><p><b>Example:</b> '+d.example+'</p><p><b>Evidence of learning:</b> '+d.evidence+'</p><p><b>Extend the inquiry:</b> '+d.extension+'</p>';place.appendChild(box)},80)})})}
function divider(){const heading=findByText(/bloom.s question builder/i);if(!heading||$('#etp-bloom-divider'))return;const node=document.createElement('div');node.id='etp-bloom-divider';node.className='etp-bloom-divider';node.setAttribute('aria-hidden','true');node.innerHTML='<svg viewBox="0 0 1100 180" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="etp-pyramid" x1="0" x2="1"><stop stop-color="#a1e863"/><stop offset=".5" stop-color="#fff200"/><stop offset="1" stop-color="#74a747"/></linearGradient></defs><g class="pulse" transform="translate(550 85)"><path d="M0 -76 L145 63 L-145 63 Z" fill="#111a12" stroke="url(#etp-pyramid)" stroke-width="4"/><path d="M0 -76 L45 -28 L-45 -28 Z" fill="#f6dd3b"/><path d="M-45 -28 L45 -28 L80 8 L-80 8 Z" fill="#a1e863"/><path d="M-80 8 L80 8 L145 63 L-145 63 Z" fill="#355c30"/><path d="M-145 63 L145 63" stroke="#fff200" stroke-width="4"/></g><path class="beam" d="M90 90 H390 M710 90 H1010" stroke="#fff200" stroke-width="3" stroke-dasharray="20 16"/><circle cx="390" cy="90" r="8" fill="#a1e863"/><circle cx="710" cy="90" r="8" fill="#a1e863"/></svg>';const section=heading.closest('section');if(section?.parentElement)section.before(node);else heading.before(node)}
function findOldBuilder(){const head=findByText(/bloom.s question builder/i);if(!head)return null;let section=head.closest('section');if(section&&section!==$('#etp-blooms-app')&&section.querySelector('input,select,textarea')&&section.textContent.length<12000&&all('input,select,textarea',section).length<18)return section;return null}
function createStudio(){if($('#etp-bloom-studio'))return;let old=findOldBuilder(),where=old||findByText(/bloom.s question builder/i);if(!where)return;let section=document.createElement('section');section.id='etp-bloom-studio';section.className='etp-bloom-studio';section.innerHTML='<h2>Bloom’s History Question Builder</h2><p>Build topic-specific inquiry questions by cognitive level. Questions appear when you choose <b>Generate Questions</b>, not while you type. Every set includes possible response guidance and a suggested evidence task.</p><p class="etp-scope">Designed for Grades 5–12 and adult history learners. Skill connections include chronology, geography, cause and consequence, sourcing, contextualization, comparison and argumentation. Align the selected questions to your district’s course standards and grade expectations.</p><div class="etp-controls"><label>Historical topic<input id="etp-bloom-topic" type="text" placeholder="e.g., Industrial Revolution or Civil War" autocomplete="off"></label><label>History lens<select id="etp-bloom-lens"><option>History</option><option>Geography</option><option>Civics & Government</option><option>Economics</option><option>Primary Sources</option><option>World History</option></select></label><label>Bloom’s level<select id="etp-bloom-level"><option value="remember">Remember</option><option value="understand">Understand</option><option value="apply">Apply</option><option value="analyze">Analyze</option><option value="evaluate">Evaluate</option><option value="create">Create</option><option value="all">All six levels</option></select></label></div><button type="button" id="etp-bloom-generate">Generate Questions</button><div class="etp-output" id="etp-bloom-output" aria-live="polite"><p>Enter a historical topic and select Generate Questions to begin.</p></div>';
where.before(section);if(old){old.hidden=true;old.setAttribute('aria-hidden','true')}
$('#etp-bloom-generate',section).addEventListener('click',generate);
const oldTopic=old?.querySelector('input[type=text]');if(oldTopic?.value)$('#etp-bloom-topic').value=oldTopic.value;
}
function generate(){const t=$('#etp-bloom-topic')?.value.trim(),lens=$('#etp-bloom-lens')?.value,level=$('#etp-bloom-level')?.value,output=$('#etp-bloom-output');if(!output)return;output.replaceChildren();if(!t){let p=document.createElement('p');p.textContent='Enter a historical topic first.';output.append(p);$('#etp-bloom-topic').focus();return}
const match=bank.find(b=>b.pattern.test(t));const chosen=level==='all'?levels:[level];let result=[],scope=document.createElement('p');scope.className='etp-scope';scope.textContent=(match?'Topic-informed questions':'Adaptable inquiry stems')+' • '+lens+' • '+chosen.map(x=>x[0].toUpperCase()+x.slice(1)).join(', ');output.append(scope);
chosen.forEach(l=>{const idx=levels.indexOf(l),questions=match?[match.q[idx],...genericQ[l](t).slice(0,3)]:genericQ[l](t);questions.forEach((q,i)=>{let answer=match&&i===0?match.answer[idx]:'Look for a historically accurate, evidence-supported response that addresses the question, uses appropriate context, and identifies uncertainty when necessary.';let article=document.createElement('article');article.className='etp-q';const label=document.createElement('strong');label.textContent=l[0].toUpperCase()+l.slice(1)+' · Question '+(i+1);const ask=document.createElement('p');ask.textContent=q;const response=document.createElement('p');response.className='etp-answer';response.textContent='Possible response / teacher look-for: '+answer;const evidence=document.createElement('p');evidence.className='etp-answer';evidence.textContent='Evidence task: '+(match?match.source:'a dated primary source, a map, and a reputable secondary account')+'. '+levelInfo[l].evidence;const copy=document.createElement('button');copy.className='etp-copy';copy.type='button';copy.textContent='Copy question';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(q);copy.textContent='Copied!'}catch{copy.textContent='Select and copy the question'}setTimeout(()=>copy.textContent='Copy question',1800)});article.append(label,ask,response,evidence,copy);output.append(article);result.push(q)})});
}
function repairDescription(){let target=all('p,small,span').find(x=>x.childElementCount===0&&/tools create adaptable question stems/i.test(x.textContent));if(target)target.textContent=target.textContent.replace(/stems[\s,.—–-]*no account/i,'stems. No account')}
function init(){if(!$('#etp-blooms-app'))return;sticky();tip();details();divider();createStudio();repairDescription()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();